import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { FiMail, FiPhone, FiMapPin, FiSend, FiMessageSquare, FiUser } from 'react-icons/fi';

const Contact = () => {
  const [formState, setFormState] = useState({
    name: '',
    email: '',
    subject: '',
    message: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);

  const handleChange = (e) => {
    setFormState({
      ...formState,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    
    // Simulate API call
    setTimeout(() => {
      setIsSubmitting(false);
      setSubmitSuccess(true);
      setFormState({
        name: '',
        email: '',
        subject: '',
        message: ''
      });
      
      // Reset success message after 3 seconds
      setTimeout(() => {
        setSubmitSuccess(false);
      }, 3000);
    }, 1500);
  };

  return (
    <div className="page-transition">
      {/* Hero Section */}
      <motion.section 
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ duration: 0.6 }}
        className="bg-gradient-to-br from-secondary-600 to-secondary-800 text-white py-20 px-4"
      >
        <div className="container mx-auto text-center">
          <motion.h1
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.2 }}
            className="text-4xl md:text-5xl font-bold mb-6"
          >
            تواصل معنا
          </motion.h1>
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5, delay: 0.4 }}
            className="text-xl max-w-3xl mx-auto"
          >
            نحن هنا للإجابة على جميع استفساراتك ومساعدتك في كل ما تحتاجه
          </motion.p>
        </div>
      </motion.section>

      {/* Contact Info Section */}
      <section className="py-16 px-4">
        <div className="container mx-auto">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-16">
            <ContactInfoCard 
              icon={<FiPhone />} 
              title="اتصل بنا" 
              info="+123 456 7890" 
              color="secondary"
              delay={0}
            />
            <ContactInfoCard 
              icon={<FiMail />} 
              title="راسلنا عبر البريد" 
              info="info@arabic-edu.com" 
              color="primary"
              delay={0.1}
            />
            <ContactInfoCard 
              icon={<FiMapPin />} 
              title="موقعنا" 
              info="شارع المعرفة، المدينة التعليمية، الدولة العربية" 
              color="accent"
              delay={0.2}
            />
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
            {/* Contact Form */}
            <motion.div
              initial={{ opacity: 0, x: -30 }}
              whileInView={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5 }}
              viewport={{ once: true }}
              className="bg-white dark:bg-gray-800 rounded-xl shadow-soft p-8 border border-gray-100 dark:border-gray-700"
            >
              <h2 className="text-2xl font-bold mb-6 text-gray-900 dark:text-white">أرسل لنا رسالة</h2>
              
              {submitSuccess && (
                <motion.div
                  initial={{ opacity: 0, y: -10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="bg-success-100 dark:bg-success-900/30 text-success-800 dark:text-success-300 p-4 rounded-lg mb-6 flex items-center"
                >
                  <FiMessageSquare className="h-5 w-5 ml-2" />
                  <span>تم إرسال رسالتك بنجاح! سنتواصل معك قريباً.</span>
                </motion.div>
              )}
              
              <form onSubmit={handleSubmit}>
                <div className="mb-6">
                  <label htmlFor="name" className="block text-gray-700 dark:text-gray-300 mb-2 font-medium">
                    الاسم
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none text-gray-500 dark:text-gray-400">
                      <FiUser />
                    </div>
                    <input
                      type="text"
                      id="name"
                      name="name"
                      value={formState.name}
                      onChange={handleChange}
                      required
                      className="input-field pr-10"
                      placeholder="أدخل اسمك الكامل"
                    />
                  </div>
                </div>
                
                <div className="mb-6">
                  <label htmlFor="email" className="block text-gray-700 dark:text-gray-300 mb-2 font-medium">
                    البريد الإلكتروني
                  </label>
                  <div className="relative">
                    <div className="absolute inset-y-0 right-0 flex items-center pr-3 pointer-events-none text-gray-500 dark:text-gray-400">
                      <FiMail />
                    </div>
                    <input
                      type="email"
                      id="email"
                      name="email"
                      value={formState.email}
                      onChange={handleChange}
                      required
                      className="input-field pr-10"
                      placeholder="أدخل بريدك الإلكتروني"
                    />
                  </div>
                </div>
                
                <div className="mb-6">
                  <label htmlFor="subject" className="block text-gray-700 dark:text-gray-300 mb-2 font-medium">
                    الموضوع
                  </label>
                  <input
                    type="text"
                    id="subject"
                    name="subject"
                    value={formState.subject}
                    onChange={handleChange}
                    required
                    className="input-field"
                    placeholder="موضوع الرسالة"
                  />
                </div>
                
                <div className="mb-6">
                  <label htmlFor="message" className="block text-gray-700 dark:text-gray-300 mb-2 font-medium">
                    الرسالة
                  </label>
                  <textarea
                    id="message"
                    name="message"
                    value={formState.message}
                    onChange={handleChange}
                    required
                    rows="5"
                    className="input-field"
                    placeholder="أدخل رسالتك هنا..."
                  ></textarea>
                </div>
                
                <motion.button
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  type="submit"
                  disabled={isSubmitting}
                  className={`btn-secondary w-full flex items-center justify-center ${isSubmitting ? 'opacity-70 cursor-not-allowed' : ''}`}
                >
                  {isSubmitting ? (
                    <>
                      <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      جاري الإرسال...
                    </>
                  ) : (
                    <>
                      <FiSend className="ml-2" />
                      إرسال الرسالة
                    </>
                  )}
                </motion.button>
              </form>
            </motion.div>
            
            {/* Map */}
            <motion.div
              initial={{ opacity: 0, x: 30 }}
              whileInView={{ opacity: 1, x: 0 }}
              transition={{ duration: 0.5 }}
              viewport={{ once: true }}
              className="rounded-xl overflow-hidden shadow-soft h-auto border border-gray-100 dark:border-gray-700"
            >
              <div className="bg-gray-200 dark:bg-gray-700 h-full min-h-[400px] flex items-center justify-center">
                <div className="text-center p-6">
                  <FiMapPin className="text-secondary-500 dark:text-secondary-400 text-5xl mx-auto mb-4" />
                  <p className="text-gray-600 dark:text-gray-300">خريطة تفاعلية ستظهر هنا</p>
                </div>
              </div>
            </motion.div>
          </div>
        </div>
      </section>

      {/* FAQ Section */}
      <section className="py-16 px-4 bg-gray-50 dark:bg-gray-800/50">
        <div className="container mx-auto">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.5 }}
            viewport={{ once: true }}
            className="text-center mb-12"
          >
            <h2 className="text-3xl font-bold mb-4 text-gray-900 dark:text-white">
              <span className="gradient-text">الأسئلة الشائعة</span>
            </h2>
            <p className="text-gray-600 dark:text-gray-400 max-w-3xl mx-auto">
              إجابات على الأسئلة الأكثر شيوعاً
            </p>
          </motion.div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 max-w-4xl mx-auto">
            <FaqItem 
              question="كيف يمكنني التسجيل في المنصة؟" 
              answer="يمكنك التسجيل بسهولة من خلال النقر على زر 'التسجيل' في الأعلى واختيار نوع الحساب (طالب أو معلم) وملء النموذج المطلوب."
              delay={0}
            />
            <FaqItem 
              question="هل الدورات مجانية؟" 
              answer="تقدم المنصة مزيجاً من الدورات المجانية والمدفوعة. يمكنك تصفح الدورات المتاحة لمعرفة تفاصيل كل دورة."
              delay={0.1}
            />
            <FaqItem 
              question="كيف يمكنني التواصل مع المعلمين؟" 
              answer="بعد التسجيل في دورة معينة، ستتمكن من التواصل مع المعلم من خلال نظام الرسائل الداخلي للمنصة."
              delay={0.2}
            />
            <FaqItem 
              question="كيف أحصل على شهادة إتمام الدورة؟" 
              answer="بعد إكمال جميع متطلبات الدورة بنجاح، ستتمكن من تحميل شهادة إتمام الدورة من لوحة التحكم الخاصة بك."
              delay={0.3}
            />
          </div>
        </div>
      </section>
    </div>
  );
};

// Contact Info Card Component
const ContactInfoCard = ({ icon, title, info, color, delay }) => {
  const colorClasses = {
    primary: "bg-primary-50 dark:bg-primary-900/30 border-primary-200 dark:border-primary-800 text-primary-600 dark:text-primary-400",
    secondary: "bg-secondary-50 dark:bg-secondary-900/30 border-secondary-200 dark:border-secondary-800 text-secondary-600 dark:text-secondary-400",
    accent: "bg-accent-50 dark:bg-accent-900/30 border-accent-200 dark:border-accent-800 text-accent-600 dark:text-accent-400",
  };

  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay }}
      viewport={{ once: true }}
      whileHover={{ y: -5 }}
      className={`rounded-xl p-6 text-center border ${colorClasses[color]} hover:shadow-lg transition-all duration-300`}
    >
      <div className="text-4xl mb-4 flex justify-center">{icon}</div>
      <h3 className="text-xl font-bold mb-2 text-gray-900 dark:text-white">{title}</h3>
      <p className="text-gray-700 dark:text-gray-300">{info}</p>
    </motion.div>
  );
};

// FAQ Item Component
const FaqItem = ({ question, answer, delay }) => {
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      whileInView={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5, delay }}
      viewport={{ once: true }}
      className="bg-white dark:bg-gray-800 rounded-xl p-6 shadow-soft border border-gray-100 dark:border-gray-700 hover:shadow-md transition-all duration-300"
    >
      <h3 className="text-lg font-bold mb-3 text-gray-900 dark:text-white">{question}</h3>
      <p className="text-gray-600 dark:text-gray-400">{answer}</p>
    </motion.div>
  );
};

export default Contact;
